/****** Object:  StoredProcedure [dbo].[spGet_DOC1Buy_IsOK]    Script Date: 2025/12/31 下午 01:33:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[spGet_DOC1Buy_IsOK] @Parameter1 int, @Parameter2 int
AS
BEGIN

DECLARE @SourceNO				NVARCHAR(300)
DECLARE @Ids					NVARCHAR(300)
DECLARE @SimulationId			NVARCHAR(300)
DECLARE @Index					INT
DECLARE @Count					INT

CREATE TABLE #TempTable1 ([SourceNO] NVARCHAR(300),[Ids] NVARCHAR(300),[SimulationId] NVARCHAR(300))
CREATE TABLE #TempTable2 ([Index] INT,[SourceNO] NVARCHAR(300),[Ids] NVARCHAR(300),[SimulationId] NVARCHAR(300))
CREATE TABLE #TempTable3 ([Ids] NVARCHAR(300))

DECLARE DetailCursor CURSOR LOCAL FOR
SELECT [SourceNO],[Id],[SimulationId] FROM
(
select b.SourceNO,a.* from SoftNetMainDB.[dbo].[DOC1BuyII] as a 
join SoftNetMainDB.[dbo].[DOC1Buy] as b on a.DOCNumberNO=b.DOCNumberNO
where a.IsOK='0'
) as Temp

OPEN DetailCursor
FETCH NEXT FROM DetailCursor INTO @SourceNO,@Ids,@SimulationId
WHILE(@@FETCH_STATUS = 0)
BEGIN
INSERT INTO #TempTable1
SELECT @SourceNO,@Ids,@SimulationId

FETCH DetailCursor INTO @SourceNO,@Ids,@SimulationId
END
CLOSE DetailCursor
DEALLOCATE DetailCursor

INSERT INTO #TempTable2 SELECT ROW_NUMBER() OVER(ORDER BY [SourceNO] ASC) AS [Index],[SourceNO],[Ids],[SimulationId] FROM #TempTable1

DECLARE DetailCursor CURSOR LOCAL FOR
SELECT [Index],[SourceNO],[Ids],[SimulationID] FROM #TempTable2

OPEN DetailCursor
FETCH NEXT FROM DetailCursor INTO @Index,@SourceNO,@Ids,@SimulationId
WHILE(@@FETCH_STATUS = 0)
BEGIN

--1
IF @SourceNO = ''
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END
--2
SET @Count = (select COUNT(*) from SoftNetMainDB.[dbo].[DOC1BuyII] where IsOK='1' and SimulationId=@SimulationId and DOCNumberNO=@SourceNO)
IF @Count > 0
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END
--3
SET @Count = (select COUNT(*) from SoftNetMainDB.[dbo].[DOC2SalesII] where IsOK='1' and SimulationId=@SimulationId and DOCNumberNO=@SourceNO)
IF @Count > 0
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END
--4
SET @Count = (select COUNT(*) from SoftNetMainDB.[dbo].[DOC3stockII] where IsOK='1' and SimulationId=@SimulationId and DOCNumberNO=@SourceNO)
IF @Count > 0
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END
--5
SET @Count = (select COUNT(*) from SoftNetMainDB.[dbo].[DOC4ProductionII] where IsOK='1' and SimulationId=@SimulationId and DOCNumberNO=@SourceNO)
IF @Count > 0
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END

SET @Count = (select COUNT(*) from SoftNetMainDB.[dbo].[DOC5OUTII] where IsOK='1' and SimulationId=@SimulationId and DOCNumberNO=@SourceNO)

IF @Count > 0
	BEGIN
	INSERT INTO #TempTable3 SELECT @Ids
	END

FETCH DetailCursor INTO @Index,@SourceNO,@Ids,@SimulationId
END
CLOSE DetailCursor
DEALLOCATE DetailCursor

--SELECT * FROM #TempTable3
IF @Parameter1 = 0 AND　@Parameter2 = 0
	BEGIN
	SELECT count(*) as Total FROM SoftNetMainDB.[dbo].[DOC1BuyII] WHERE Id in (SELECT * FROM #TempTable3)
	END
ELSE
	BEGIN
	SELECT * FROM SoftNetMainDB.[dbo].[DOC1BuyII] WHERE Id in (SELECT * FROM #TempTable3)
	ORDER BY ArrivalDate,PartNO,Id
	OFFSET @Parameter1 ROWS 
	FETCH NEXT @Parameter2 ROWS ONLY;
	END

DROP TABLE #TempTable1
DROP TABLE #TempTable2
DROP TABLE #TempTable3

END
GO
